bash_results.command:
cd homework; cat > /tmp/ctx.py <<'E'
import ast,glob,sys
bad={'sid','kv','refs','norm','cwd'}
for f in sorted(glob.glob('**/*.py',recursive=True)):
  src=open(f).read().split('\n'); seen={}
  for n in ast.walk(ast.parse('\n'.join(src))):
    w=getattr(n,'id',None) or getattr(n,'arg',None) or getattr(n,'name',None) or getattr(n,'asname',None)
    if w and (w in bad or len(w)==1 and w not in '_nkei'): seen.setdefault(w,set()).add(n.lineno)
  for w,ls in seen.items():
    print('##',f.split('/')[-1],w)
    for l in sorted(ls)[:3]: print('  ',l,src[l-1].strip()[:150])
E
python3 -I /tmp/ctx.py

